[{"id":"db11e06","elType":"container","settings":{"flex_direction":"column"},"elements":[],"isInner":false},{"id":"dc9e0df","elType":"container","settings":{"flex_direction":"column","content_width":"full"},"elements":[{"id":"9a4ea03","elType":"widget","settings":{"html":"<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Jyotirmath Peetham | Uttaramnaya Peeth | Shivala</title>

    <meta name="description" content="Authentic Guru Parampara of Uttaramnaya Jyotirmath Peeth, Joshimath. Established by Adi Shankaracharya.">
    <meta name="keywords" content="Jyotirmath Peetham, Uttaramnaya Peeth, Adi Shankaracharya, Totakacharya, Brahmananda Saraswati, Swami Avimukteshwaranand">

    <link href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css" rel="stylesheet">
    <link href="https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700;800&family=Lato:wght@300;400;700&family=Alegreya:wght@400;700&display=swap" rel="stylesheet">

    <link rel="stylesheet" href="peeth-style.css">
</head>
<body data-lang="hi">

    <div class="bg-pattern"></div>

    <!-- Language Switcher -->
    <div class="lang-switcher">
        <button class="lang-btn" onclick="changeLanguage('en')" id="btn-en">English</button>
        <button class="lang-btn active" onclick="changeLanguage('hi')" id="btn-hi">हिन्दी</button>
    </div>

    <!-- Hero Section -->
    <section class="profile-hero">
        <div class="hero-text-col">
            <span class="peeth-tag">
                <span class="en">The Northern Āmnāya Pīṭham</span>
                <span class="hi">उत्तराम्नाय पीठम</span>
            </span>
            <h1 class="main-title">
                <span class="en">Jyotirmath Peetham</span>
                <span class="hi">ज्योतिर्मठ पीठ</span>
            </h1>
            <p class="sub-title">
                <span class="en">Joshimath, Uttarakhand | Established by Jagadguru Adi Shankaracharya</span>
                <span class="hi">जोशीमठ, उत्तराखंड | जगद्गुरु आदि शंकराचार्य द्वारा स्थापित</span>
            </p>

            <div class="info-grid">
                <div class="info-item">
                    <span class="info-label"><span class="en">Veda</span><span class="hi">वेद</span></span>
                    <div class="info-val"><span class="en">Atharva Veda</span><span class="hi">अथर्ववेद</span></div>
                </div>
                <div class="info-item">
                    <span class="info-label"><span class="en">Mahavakya</span><span class="hi">महावाक्य</span></span>
                    <div class="info-val"><span class="en">Ayam Ātmā Brahma</span><span class="hi">अयमात्मा ब्रह्म</span></div>
                </div>
                <div class="info-item">
                    <span class="info-label"><span class="en">First Acharya</span><span class="hi">प्रथम आचार्य</span></span>
                    <div class="info-val"><span class="en">Sri Totakacharya</span><span class="hi">श्री तोटकाचार्य</span></div>
                </div>
            </div>
        </div>

        <div class="hero-image-col">
            <div class="portrait-frame">
                <img src="http://shivbodhtrust.org/wp-content/uploads/2026/03/jyotirmath.png" alt="Jyotirmath Peetham" class="main-img">
                <div class="img-caption">
                    <span class="en">The Divine Seat of Jyotirmath, Himalayas</span>
                    <span class="hi">हिमालय में स्थित ज्योतिर्मठ का दिव्य पीठ</span>
                </div>
            </div>
        </div>
    </section>

    <!-- Content Section -->
    <article class="content-container">

        <div class="highlight-box">
            <div class="highlight-icon"><i class="fas fa-om"></i></div>
            <h3 style="font-family:'Cinzel', serif; color:#C0392B; margin-bottom:10px;">
                <span class="en">The Spiritual Capital of the North</span>
                <span class="hi">उत्तर भारत की आध्यात्मिक राजधानी</span>
            </h3>
            <p style="margin:0; font-style:italic; text-align: justify;" class="en">
                Jyotirmath, also known as Joshimath, is the northern monastery established by Adi Shankaracharya in the 8th century. Situated in the holy Himalayas en route to Badrinath, this Peetham is entrusted with the profound responsibility of preserving the Atharva Veda and the Advaita Vedanta tradition.
            </p>
            <p style="margin:0; font-style:italic; text-align: justify;" class="hi">
                ज्योतिर्मठ (जोशीमठ) आदि शंकराचार्य द्वारा 8वीं शताब्दी में स्थापित उत्तरी मठ है। बद्रीनाथ के मार्ग पर पवित्र हिमालय में स्थित, इस पीठ को अथर्ववेद और अद्वैत वेदांत परंपरा के संरक्षण का दिव्य उत्तरदायित्व सौंपा गया है।
            </p>
        </div>

        <!-- PURE & AUTHENTIC GURU PARAMPARA LIST -->
        <div class="parampara-section" style="margin-top: 50px;">
            <h2 class="chapter-heading" style="justify-content: center; text-align: center;">
                <span class="en">The Sacred Guru Parampara</span>
                <span class="hi">पवित्र गुरु परम्परा</span>
            </h2>
            <p style="text-align:center; color:var(--text-gray); margin-bottom: 30px;">
                <span class="en">The illustrious and unbroken spiritual lineage of Jyotirmath</span>
                <span class="hi">आदि शंकराचार्य से ज्योतिर्मठ की प्रामाणिक और गौरवशाली आध्यात्मिक वंशावली</span>
            </p>

            <div class="rich-box" style="padding: 30px; background: #fff; border: 1px solid var(--gold-accent); border-radius: 10px;">

                <!-- 1. Adi Shankaracharya -->
                <div class="guru-row">
                    <div class="guru-icon">1</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Jagadguru Adi Shankaracharya</span><span class="hi">जगद्गुरु आदि शंकराचार्य</span></span>
                        <span class="guru-period"><span class="en">8th Century CE (Approx)</span><span class="hi">8वीं शताब्दी ई. (लगभग)</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">The Supreme Founder of the four cardinal Peethams.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">चारों पीठों के संस्थापक।</p>
                    </div>
                </div>

                <!-- 2. Sri Totakacharya -->
                <div class="guru-row">
                    <div class="guru-icon">2</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Totakacharya</span><span class="hi">स्वामी तोटकाचार्य</span></span>
                        <span class="guru-period"><span class="en">8th Century CE</span><span class="hi">8वीं शताब्दी ई.</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Chief disciple of Adi Shankaracharya and the First Acharya of this Peetham.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">आदि शंकराचार्य के प्रमुख शिष्य और इस पीठ के प्रथम आचार्य।</p>
                    </div>
                </div>

                <!-- 3. Swami Brahmananda Saraswati -->
                <div class="guru-row">
                    <div class="guru-icon">3</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Brahmananda Saraswati</span><span class="hi">स्वामी ब्रह्मानंद सरस्वती</span></span>
                        <span class="guru-period"><span class="en">1941 – 1953</span><span class="hi">1941 – 1953</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Ascended the throne in 1941 with the cooperation of the Acharyas of the other three Peethams, reviving the profound glory of Jyotirmath.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">आधुनिक काल में तीनों पीठों (पुरी, शृंगेरी व द्वारका) के आचार्यों के सहयोग से 1941 में गद्दी पर बैठे और ज्योतिर्मठ के पूर्ण गौरव को स्थापित किया। 1953 में इनका स्वर्गवास हुआ।</p>
                    </div>
                </div>

                <!-- 4. Swami Shantanand Saraswati -->
                <div class="guru-row">
                    <div class="guru-icon">4</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Shantanand Saraswati</span><span class="hi">स्वामी शांतानंद सरस्वती</span></span>
                        <span class="guru-period"><span class="en">1953 – 1980</span><span class="hi">1953 – 1980</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Ascended the Peetham carrying forward the profound spiritual traditions of Brahmananda Saraswati.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">स्वामी ब्रह्मानंद सरस्वती जी की आध्यात्मिक परंपरा का निर्वहन करते हुए गद्दी पर विराजमान हुए।</p>
                    </div>
                </div>

                <!-- 5. Swami Krishnabodhashram -->
                <div class="guru-row">
                    <div class="guru-icon">5</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Krishnabodhashram</span><span class="hi">स्वामी कृष्णबोधाश्रम</span></span>
                        <span class="guru-period"><span class="en">1953 – 1973</span><span class="hi">1953 – 1973</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Eminent scholar and Acharya recognized by the Vidvat Parishad of Banaras.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">बनारस के विद्वत परिषद द्वारा सम्मानित प्रकांड विद्वान और आचार्य।</p>
                    </div>
                </div>

                <!-- 6. Swami Shankaranand Saraswati -->
                <div class="guru-row">
                    <div class="guru-icon">6</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Shankaranand Saraswati</span><span class="hi">स्वामी शंकरानंद सरस्वती</span></span>
                        <span class="guru-period"><span class="en">1973</span><span class="hi">1973</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Successor to Swami Krishnabodhashram.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">स्वामी कृष्णबोधाश्रम जी के परम योग्य उत्तराधिकारी।</p>
                    </div>
                </div>

                <!-- 7. Swami Vishnudevanand Saraswati -->
                <div class="guru-row">
                    <div class="guru-icon">7</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Vishnudevanand Saraswati</span><span class="hi">स्वामी विष्णुदेवानंद सरस्वती</span></span>
                        <span class="guru-period"><span class="en">1980 – 1990</span><span class="hi">1980 – 1990</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Eminent spiritual leader and successor to Swami Shantanand Saraswati.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">स्वामी शांतानंद सरस्वती जी द्वारा नियुक्त महान आध्यात्मिक उत्तराधिकारी।</p>
                    </div>
                </div>

                <!-- 8. Swami Swaroopananda Saraswati -->
                <div class="guru-row">
                    <div class="guru-icon">8</div>
                    <div class="guru-details">
                        <span class="guru-name-title"><span class="en">Swami Swaroopananda Saraswati</span><span class="hi">स्वामी स्वरूपानंद सरस्वती</span></span>
                        <span class="guru-period"><span class="en">1973 – 2022</span><span class="hi">1973 – 2022</span></span>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="en">Became Acharya of Jyotirmath in 1973 and also Dwarka Peeth in 1982. Counted among the greatest and longest-serving Acharyas of Sanatana Dharma.</p>
                        <p style="font-size: 0.95em; color: #555; margin-top: 5px;" class="hi">1973 में ज्योतिर्मठ और 1982 में द्वारका पीठ के भी आचार्य बने। सनातन धर्म के सबसे महान और लंबे समय तक रहने वाले आचार्यों में गिने जाते हैं।</p>
                    </div>
                </div>

                <!-- 9. Swami Avimukteshwaranand Saraswati (Current) -->
                <div class="guru-row current">
                    <div class="guru-icon">9</div>
                    <div class="guru-details">
                        <span class="guru-name-title" style="color: #C0392B;">
                            <span class="en">Swami Avimukteshwaranand Saraswati</span>
                            <span class="hi">स्वामी अविमुक्तेश्वरानंद सरस्वती</span>
                        </span>
                        <span class="guru-period" style="font-weight: bold;">
                            <span class="en">2022 – Present</span>
                            <span class="hi">2022 – वर्तमान</span>
                        </span>
                        <p style="font-size: 1.05em; color: #C0392B; margin-top: 5px; font-weight: 600;" class="en">
                            The direct disciple of Swami Swaroopananda Saraswati. He is the authentic, universally accepted Shankaracharya. The followers of Sanatana Dharma unanimously revere him as their true spiritual guide and Acharya.
                        </p>
                        <p style="font-size: 1.05em; color: #C0392B; margin-top: 5px; font-weight: 600;" class="hi">
                            स्वामी स्वरूपानंद सरस्वती जी के शिष्य। यही प्रामाणिक और परंपरा द्वारा सर्वमान्य आचार्य हैं। सनातन धर्म को मानने वाली पूरी जनता एक मत से इन्हें अपना सच्चा जगद्गुरु शंकराचार्य स्वीकार कर चुकी है।
                        </p>
                    </div>
                </div>

            </div>
        </div>
    </article>

    <script>
        function changeLanguage(lang) {
            document.body.setAttribute('data-lang', lang);
            document.getElementById('btn-en').classList.remove('active');
            document.getElementById('btn-hi').classList.remove('active');
            document.getElementById('btn-' + lang).classList.add('active');
        }
    </script>
</body>
</html>
","custom_css":"/* PEETHAM THEME VARIABLES */
:root {
    --paper-bg: #FDFBF7;
    --saffron-dark: #C0392B; /* Deep Temple Red */
    --saffron-light: #E67E22;
    --gold-accent: #D4AF37;
    --text-dark: #2C3E50;
    --text-gray: #5D6D7E;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

body {
    background-color: var(--paper-bg); 
    color: var(--text-dark); 
    font-family: 'Lato', sans-serif; 
    line-height: 1.8; 
    overflow-x: hidden;
}

/* =========================================
   LANGUAGE SWITCHER LOGIC & STYLES 
========================================= */
body[data-lang="en"] .hi { display: none !important; }
body[data-lang="hi"] .en { display: none !important; }

.lang-switcher {
    position: absolute; top: 30px; right: 5%; z-index: 1000;
    display: flex; gap: 5px; background: #fff; padding: 5px;
    border-radius: 30px; box-shadow: 0 4px 10px rgba(0,0,0,0.1);
    border: 2px solid var(--gold-accent);
}
.lang-btn {
    background: transparent; border: none; padding: 6px 15px;
    border-radius: 20px; font-family: 'Lato', sans-serif; font-weight: 700;
    color: var(--text-dark); cursor: pointer; transition: 0.3s;
}
.lang-btn.active {
    background: var(--saffron-dark); color: #fff;
}

/* Background Pattern */
.bg-pattern {
    position: fixed; top: 0; left: 0; width: 100%; height: 100%; 
    background-image: radial-gradient(var(--gold-accent) 0.5px, transparent 0.5px); 
    background-size: 30px 30px; opacity: 0.2; z-index: -1;
}

/* HERO SECTION */
.profile-hero {
    display: flex; flex-wrap: wrap; align-items: center; justify-content: center; 
    min-height: 80vh; padding: 100px 5% 50px; gap: 50px; max-width: 1400px; margin: 0 auto;
}

.hero-text-col { flex: 1; min-width: 350px; }
.peeth-tag {
    display: inline-block; color: var(--saffron-light); font-weight: 700; 
    letter-spacing: 2px; text-transform: uppercase; font-size: 0.9rem; 
    margin-bottom: 10px; border-bottom: 2px solid var(--saffron-light); padding-bottom: 5px;
}
.main-title {
    font-family: 'Cinzel', serif; font-size: clamp(2.5rem, 5vw, 4rem); 
    color: var(--saffron-dark); line-height: 1.1; margin-bottom: 15px;
}
.sub-title { font-size: 1.3rem; color: var(--text-gray); font-weight: 300; margin-bottom: 30px; }

/* Info Grid */
.info-grid {
    display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); 
    gap: 20px; margin-top: 30px;
}
.info-item {
    background: #fff; border-left: 4px solid var(--gold-accent); 
    padding: 15px 20px; box-shadow: 0 5px 15px rgba(0,0,0,0.05);
}
.info-label {
    font-size: 0.75rem; text-transform: uppercase; color: var(--text-gray); 
    letter-spacing: 1px; display: block;
}
.info-val {
    font-family: 'Cinzel', serif; font-size: 1.1rem; color: var(--saffron-dark); font-weight: 700;
}

/* IMAGE COL */
.hero-image-col { flex: 1; min-width: 300px; max-width: 500px; position: relative; }
.portrait-frame {
    position: relative; border-radius: 20px 20px 0 0; padding: 15px; 
    background: #fff; box-shadow: 0 20px 50px rgba(0,0,0,0.15); border: 1px solid var(--gold-accent);
}
.main-img { width: 100%; height: auto; border-radius: 10px 10px 0 0; display: block; }
.img-caption {
    text-align: center; background: var(--saffron-dark); color: #fff; 
    padding: 10px; font-family: 'Cinzel', serif; font-size: 0.9rem; letter-spacing: 1px;
}

/* CONTENT BODY */
.content-container { max-width: 900px; margin: 0 auto 80px; padding: 0 25px; }

.chapter-heading {
    font-family: 'Cinzel', serif; font-size: 2rem; color: var(--text-dark); 
    margin: 50px 0 20px; display: flex; align-items: center; gap: 15px;
}
.chapter-heading::before {
    content: ""; width: 40px; height: 2px; background: var(--gold-accent);
}

.highlight-box {
    background: #FFFBF0; border: 1px solid var(--gold-accent); 
    padding: 30px; border-radius: 8px; position: relative; margin: 40px 0;
}
.highlight-icon {
    position: absolute; top: -20px; left: 30px; background: var(--saffron-dark); 
    color: #fff; width: 40px; height: 40px; display: flex; align-items: center; 
    justify-content: center; border-radius: 50%; font-size: 1.2rem; border: 2px solid var(--gold-accent);
}

/* GURU PARAMPARA LIST */
.guru-row {
    display: flex; gap: 20px; align-items: flex-start; padding: 15px 0; 
    border-bottom: 1px dashed rgba(212, 175, 55, 0.3);
}
.guru-row:last-child { border-bottom: none; }

.guru-icon {
    flex-shrink: 0; width: 50px; height: 50px; border: 2px solid var(--gold-accent); 
    border-radius: 50%; display: flex; align-items: center; justify-content: center; 
    font-weight: 700; color: #8B4513; background: #FFF8F0; font-family: 'Cinzel', serif; font-size: 1.1em;
}

.guru-details { flex-grow: 1; }
.guru-name-title { font-size: 1.25em; color: #4a2c0f; font-weight: 700; display: block; }
.guru-period { display: block; font-size: 0.9em; color: #888; margin-top: 5px; }

/* Current Acharya Highlight */
.guru-row.current {
    background: linear-gradient(to right, rgba(212, 175, 55, 0.1), transparent); 
    border-radius: 10px; padding: 20px; border: 1px solid var(--gold-accent);
}
.guru-row.current .guru-icon {
    background: var(--saffron-dark); color: #fff; border-color: var(--saffron-dark);
}
.guru-row.current .guru-name-title { color: var(--saffron-dark); font-size: 1.4em; }

/* MEDIA QUERIES */
@media (max-width: 768px) {
    .profile-hero { flex-direction: column-reverse; text-align: center; padding-top: 100px; }
    .hero-image-col { width: 100%; }
    .info-grid { text-align: left; }
    .chapter-heading::before { display: none; }
    .chapter-heading { justify-content: center; text-align: center; }
    .lang-switcher { top: 20px; right: 50%; transform: translateX(50%); }
}
